def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # A full-length line of 2 is the divider; extend the adjacent object's
    # far boundary by one full line of 8.
    vertical = next(
        (c for c in range(w) if all(grid[r][c] == 2 for r in range(h))),
        None
    )
    horizontal = next(
        (r for r in range(h) if all(value == 2 for value in grid[r])),
        None
    )

    out = [row[:] for row in grid]

    if vertical is not None:
        for side in (-1, 1):
            near = vertical + side
            if not (0 <= near < w):
                continue
            if not any(grid[r][near] not in (bg, 2) for r in range(h)):
                continue
            edge = near
            while 0 <= edge + side < w and any(
                grid[r][edge + side] not in (bg, 2) for r in range(h)
            ):
                edge += side
            target = edge + side
            if 0 <= target < w:
                for r in range(h):
                    out[r][target] = 8
            return out

    if horizontal is not None:
        for side in (-1, 1):
            near = horizontal + side
            if not (0 <= near < h):
                continue
            if not any(value not in (bg, 2) for value in grid[near]):
                continue
            edge = near
            while 0 <= edge + side < h and any(
                value not in (bg, 2) for value in grid[edge + side]
            ):
                edge += side
            target = edge + side
            if 0 <= target < h:
                out[target] = [8] * w
            return out

    return out
